solution.solution.cpp:
#include <vector>

using Grid = std::vector<std::vector<int>>;

Grid transpose(const Grid& grid)
{
    const std::size_t rows{ grid.size() };
    const std::size_t cols{ grid[0].size() };
    Grid result(cols, std::vector<int>(rows));
    for (std::size_t r{ 0 }; r < rows; ++r)
    {
        for (std::size_t c{ 0 }; c < cols; ++c)
        {
            result[c][r] = grid[r][c];
        }
    }
    return result;
}

unitTests:
TEST("two by three") { CHECK_EQ(transpose({ { 1, 2, 3 }, { 4, 5, 6 } }), (Grid{ { 1, 4 }, { 2, 5 }, { 3, 6 } })); }
TEST("a single row becomes a column") { CHECK_EQ(transpose({ { 7, 8, 9 } }), (Grid{ { 7 }, { 8 }, { 9 } })); }
TEST("twice gives the original") { const Grid g{ { 1, 2 }, { 3, 4 }, { 5, 6 } }; CHECK_EQ(transpose(transpose(g)), g); }

